Here are the MSTest comparison assertions you need for boundary testing your `ScoreCalculator`:

## Comparison Assertions (MSTest 3.x+)

```csharp
Assert.IsGreaterThan(lowerBound, actual);   // actual > lowerBound
Assert.IsLessThan(upperBound, actual);      // actual < upperBound
Assert.IsInRange(actual, low, high);        // low <= actual <= high
```

## Example Tests

```csharp
[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calc = new();

    [TestMethod]
    [DataRow(7, 10, 70.0)]
    [DataRow(10, 10, 100.0)]
    [DataRow(0, 5, 0.0)]
    public void CalculatePercentage_ValidInputs_ReturnsExpected(int correct, int total, double expected)
    {
        var result = _calc.CalculatePercentage(correct, total);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void CalculatePercentage_ResultIsInRange()
    {
        var result = _calc.CalculatePercentage(3, 7);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    [DataRow(90.0, "A")]
    [DataRow(89.9, "B")]
    [DataRow(80.0, "B")]
    [DataRow(79.9, "C")]
    [DataRow(70.0, "C")]
    [DataRow(69.9, "D")]
    [DataRow(60.0, "D")]
    [DataRow(59.9, "F")]
    public void GetGrade_AtBoundary_ReturnsCorrectGrade(double percentage, string expected)
    {
        Assert.AreEqual(expected, _calc.GetGrade(percentage));
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        var result = _calc.NormalizeScore(120, 100);
        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ValidInput_ResultIsGreaterThanZero()
    {
        var result = _calc.NormalizeScore(50, 200);
        Assert.IsGreaterThan(0.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ValidInput_ResultIsInRange()
    {
        var result = _calc.NormalizeScore(50, 200);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(5, 0));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(11, 10));
    }
}
```

## Key Takeaways

| Scenario | Assertion |
|----------|-----------|
| Value within bounds | `Assert.IsInRange(actual, low, high)` |
| Value above a threshold | `Assert.IsGreaterThan(lowerBound, actual)` |
| Value below a cap | `Assert.IsLessThan(upperBound, actual)` |
| Exact boundary values (grade cutoffs) | `Assert.AreEqual(expected, actual)` with `[DataRow]` at each boundary |
| Invalid input throws | `Assert.ThrowsExactly<T>(() => ...)` |

The `[DataRow]` tests at grade boundaries (90, 80, 70, 60) and just below (89.9, 79.9, etc.) are the most important pattern here — they verify behavior changes exactly at the cutoff points.
